import hashlib,importlib.util,json,os,platform,re,tempfile
from pathlib import Path

root=Path.cwd();spec=importlib.util.spec_from_file_location('bench',root/'scripts/benchmark_snapshot_integration.py')
bench=importlib.util.module_from_spec(spec);spec.loader.exec_module(bench)
out=root.parent/'followup-results';out.mkdir(exist_ok=False);fixtures=out/'fixtures';fixtures.mkdir()
env=dict(os.environ,GOMAXPROCS='2',CGO_ENABLED='0',TMPDIR=str(fixtures))
cases=[('watch-small','./internal/snapshot','^BenchmarkWatchPreparation$/^1000$/^retained-edit$','10x')] if platform.system()=='Darwin' else [('push','./cmd/errand','^BenchmarkPushPhases$','3x'),('submission','./cmd/errand','^BenchmarkWorkspaceCreationAndSubmission$/^ephemeral-job$','3x')]
report={'scope':'Focused followups for slower main-matrix observations, no code changes','script':Path(__file__).read_text(),'platform':platform.platform(),'filesystem':bench.filesystem(fixtures,env,out,'fixture-filesystem'),'orders':[],'versions':{}}
with tempfile.TemporaryDirectory(dir='/tmp') as p:
 report['default_tmp_filesystem']=bench.filesystem(Path(p),env,out,'default-tmp-filesystem')
for name,source in [('baseline',root.parent/'baseline'),('candidate',root)]:
 directory=out/name;directory.mkdir();digest=hashlib.sha256()
 for p in sorted([*source.rglob('*.go'),source/'go.mod',source/'go.sum']):digest.update(str(p.relative_to(source)).encode()+b'\0'+p.read_bytes()+b'\0')
 report['versions'][name]={'source_sha256':digest.hexdigest(),'samples':[],'binaries':{}}
 for key,package,_,_ in cases:
  binary=directory/(key+'.test');bench.run(['go','test','-c','-o',str(binary),package],source,env,directory/('build-'+key+'.txt'))
  report['versions'][name]['binaries'][key]=hashlib.sha256(binary.read_bytes()).hexdigest()
for number in range(5):
 order=['baseline','candidate'] if number%2==0 else ['candidate','baseline'];report['orders'].append(order)
 for name in order:
  directory=out/name;source=root if name=='candidate' else root.parent/'baseline'
  for key,_,pattern,duration in cases:
   raw=bench.run([str(directory/(key+'.test')),'-test.v','-test.run=^$','-test.bench='+pattern,'-test.benchtime='+duration,'-test.benchmem','-test.timeout=10m'],source,env,directory/(str(number)+'-'+key+'.txt'))
   samples=[]
   for line in raw.splitlines():
    m=re.match(r'^(Benchmark\S+)-\d+\s+(\d+)\s+(.+)$',line)
    if m:
     values=m[3].split();samples.append({'name':m[1],'round':number,'iterations':int(m[2]),'metrics':{values[i+1]:float(values[i]) for i in range(0,len(values),2)}})
   if len(samples)!=1:raise RuntimeError((key,len(samples)))
   report['versions'][name]['samples']+=samples
  (out/'report.json').write_text(json.dumps(report,indent=2)+'\n');print(f'Round {number+1}/5: {name} complete',flush=True)
for name in report['versions']:
 for key,_,_,_ in cases:(out/name/(key+'.test')).unlink()

